  // -----------------------------
  userStoryResult.epics = userStoryResult.epics.map(epic => ({
    epic_name: epic.epic_name || "Untitled Epic",
    description: epic.description || "",
    features: Array.isArray(epic.features)
      ? epic.features
      : []
  }));

  // -----------------------------
  // Validate Features
  // -----------------------------
  userStoryResult.epics.forEach(epic => {

    epic.features = epic.features.map(feature => ({
      feature_name: feature.feature_name || "Unnamed Feature",
      user_stories: Array.isArray(feature.user_stories)
        ? feature.user_stories
        : []
    }));

  });

  // -----------------------------
  // Validate Stories
  // -----------------------------
  userStoryResult.epics.forEach(epic => {

    epic.features.forEach(feature => {

      feature.user_stories = feature.user_stories.map((story, index) => ({

        story_id:
          story.story_id ||
          story.id ||
          `US-${index + 1}`,

        title: story.title || "",

        story: story.story || "",

        business_value:
          story.business_value || "",

