try {

  let finalDocument;

  // -------------------------
  // Parse JSON
  // -------------------------

  if (typeof aiResponse === "string") {

    const cleanResponse = aiResponse
      .replace(/```json/g, "")
      .replace(/```/g, "")
      .trim();

    finalDocument = JSON.parse(cleanResponse);

  } else {

    finalDocument = aiResponse;

  }

  // -------------------------
  // Validation
  // -------------------------

  finalDocument.document_title = finalDocument.document_title || "Product Documentation";
  finalDocument.version = finalDocument.version || "1.0";
  finalDocument.generated_on =
    finalDocument.generated_on || new Date().toLocaleString();

  finalDocument.sections = finalDocument.sections || [];
  finalDocument.table_of_contents =
    finalDocument.table_of_contents || [];
  finalDocument.appendix = finalDocument.appendix || [];
  finalDocument.references = finalDocument.references || [];
  finalDocument.next_steps = finalDocument.next_steps || [];

  // =====================================================
  // Generate Professional Document
  // =====================================================

  let markdown = "";

  markdown += `${finalDocument.document_title.toUpperCase()}\n`;
  markdown += "=".repeat(90) + "\n\n";

  markdown += `Version      : ${finalDocument.version}\n`;
  markdown += `Generated On : ${finalDocument.generated_on}\n\n`;

  // -----------------------------------------------------

  if(finalDocument.table_of_contents.length){

      markdown += "=".repeat(90) + "\n";
      markdown += "TABLE OF CONTENTS\n";
      markdown += "=".repeat(90) + "\n\n";

      finalDocument.table_of_contents.forEach((item,index)=>{

          markdown += `${index+1}. ${item}\n`;

      });

      markdown += "\n\n";

  }

  // -----------------------------------------------------

  finalDocument.sections.forEach((section,index)=>{

      markdown += "=".repeat(90) + "\n";
      markdown += `${index+1}. ${section.title.toUpperCase()}\n`;
      markdown += "=".repeat(90) + "\n\n";

      markdown += `${section.content}\n\n`;

  });

  // -----------------------------------------------------

  if(finalDocument.appendix.length){

      markdown += "=".repeat(90) + "\n";
      markdown += "APPENDIX\n";
      markdown += "=".repeat(90) + "\n\n";

      finalDocument.appendix.forEach(item=>{

          markdown += `• ${item}\n`;

      });

      markdown += "\n";

  }

  // -----------------------------------------------------

  if(finalDocument.references.length){

      markdown += "=".repeat(90) + "\n";
      markdown += "REFERENCES\n";
      markdown += "=".repeat(90) + "\n\n";

      finalDocument.references.forEach(item=>{

          markdown += `• ${item}\n`;

      });

      markdown += "\n";

  }

  // -----------------------------------------------------

  if(finalDocument.next_steps.length){

      markdown += "=".repeat(90) + "\n";
      markdown += "NEXT STEPS\n";
      markdown += "=".repeat(90) + "\n\n";

      finalDocument.next_steps.forEach(item=>{

          markdown += `• ${item}\n`;

      });

      markdown += "\n";

  }

  // =====================================================
  // Return
  // =====================================================

  return [
    {
      json: {

        title: finalDocument.document_title,

        markdown: markdown,

        finalDocument: finalDocument,

        summary: {

          title: finalDocument.document_title,

          version: finalDocument.version,

          total_sections: finalDocument.sections.length,

          generated_on: finalDocument.generated_on

        }

      }
    }
  ];

} catch (error) {

  console.error(error);

  throw new Error(
    `Final Documentation Parse Error: ${error.message}`
  );

